"""`figures render` and `figures check`: script discovery, stable ids, drift detection.

The scripts here write an SVG without Graphviz, so the mechanics are tested everywhere;
drawing the real figures needs the `figures` dependency group and `dot`.
"""

from __future__ import annotations

from pathlib import Path

from app.cli.figures_cmds import check, figure_scripts, render, stabilize

SCRIPT = """import pathlib
pathlib.Path(__file__).with_suffix(".svg").write_text(
    '<!-- Generated by graphviz version 14 -->\\n'
    '<svg xmlns="http://www.w3.org/2000/svg"><g id="node1"><title>{a}</title></g>'
    '<g id="edge1"><title>{a}&#45;&gt;{b}</title></g></svg>', encoding="utf-8")
"""
A, B = "a" * 32, "b" * 32


def _pack(root: Path, slug: str, scripts: dict[str, str]) -> Path:
    figures = root / slug / "figures"
    figures.mkdir(parents=True)
    for name, body in scripts.items():
        (figures / f"{name}.py").write_text(body, encoding="utf-8")
    return root / slug


def test_scripts_are_found_per_pack_in_order(tmp_path: Path) -> None:
    _pack(tmp_path, "pack-b", {"zeta": SCRIPT, "alpha": SCRIPT})
    _pack(tmp_path, "pack-a", {"one": SCRIPT})
    (tmp_path / "pack-c").mkdir()  # a pack without figures
    found = [f"{s.parent.parent.name}/{s.name}" for s in figure_scripts(tmp_path)]
    assert found == ["pack-a/one.py", "pack-b/alpha.py", "pack-b/zeta.py"]
    assert [s.name for s in figure_scripts(tmp_path, "pack-b")] == ["alpha.py", "zeta.py"]


def test_stabilize_names_random_ids_in_order_and_drops_comments() -> None:
    svg = f"<!-- v14 -->\n<svg><title>{B}</title><title>{A}</title><title>{B}</title></svg>"
    assert stabilize(svg) == "<svg><title>n1</title><title>n2</title><title>n1</title></svg>"


def test_render_writes_a_stable_drawing_beside_the_script(tmp_path: Path) -> None:
    pack = _pack(tmp_path, "pack", {"fig": SCRIPT.format(a=A, b=B)})
    svg = render(pack / "figures" / "fig.py")
    assert svg == pack / "figures" / "fig.svg"
    text = svg.read_text(encoding="utf-8")
    assert "<title>n1</title>" in text and "n1&#45;&gt;n2" in text
    assert A not in text and "Generated by" not in text


def test_check_passes_on_a_fresh_render_and_catches_drift(tmp_path: Path) -> None:
    pack = _pack(tmp_path, "pack", {"fig": SCRIPT.format(a=A, b=B)})
    script = pack / "figures" / "fig.py"
    assert check(script) is not None  # nothing committed yet
    render(script)
    assert check(script) is None
    # A hand edit to the SVG, or a script that now draws something else, is drift.
    svg = script.with_suffix(".svg")
    svg.write_text(svg.read_text(encoding="utf-8").replace("edge1", "edge9"), encoding="utf-8")
    assert "run `make figures`" in (check(script) or "")
